 const saveClass=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!slot)return;const f=new FormData(e.currentTarget),selectedStudentId=String(f.get('studentId')||''),student=students.find(s=>sameId(s.id,selectedStudentId)),court=String(f.get('court')||slot.court),type=String(f.get('type')) as ClassItem['type'];if(!student)return;const clash=slotConflict(classes,{date:slot.date,time:slot.time,court,studentId:student.id});if(clash==='alumno'){alert('Este alumno ya está asignado a este horario.');return}if(clash==='cupo'){alert('Este horario ya tiene 4 alumnos. No se pueden agregar más.');return}const recurrenceId=type==='recurrente'?newId():undefined,id=recurrenceId?scheduleClassId(recurrenceId,slot.date):newId();setClasses(xs=>[...xs,{id,studentId:student.id,student:student.name,date:slot.date,time:slot.time,court,duration:Number(f.get('duration')||60),type,status:'Programada',recurrenceId,cycleId:cycleFor(student.id)?.id}]);if(recurrenceId){const rule:Recurrence={id:recurrenceId,studentId:student.id,days:[weekdayOf(slot.date)],time:slot.time,duration:Number(f.get('duration')||60),court,start:slot.date,active:true};setRecurrences(xs=>[...xs,rule])}setModal(null);setSlot(null)}
 const moveClass=(item:ClassItem,targetDate:string,targetTime:string)=>{const conflict=visible.some(c=>!sameId(c.id,item.id)&&c.date===targetDate&&c.time===targetTime&&c.court===item.court&&c.status!=='Cancelada');if(conflict){alert('Este horario ya está ocupado.');return}if(item.recurrenceId){setRecurrences(xs=>xs.map(r=>sameId(r.id,item.recurrenceId)?{...r,days:[weekdayOf(targetDate)],time:targetTime}:r));setClasses(xs=>xs.map(c=>sameId(c.id,item.id)?{...c,date:targetDate,time:targetTime}:c))}else setClasses(xs=>xs.map(c=>sameId(c.id,item.id)?{...c,date:targetDate,time:targetTime}:c));setSelectedClass(null)}
 const saveCycle=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget),rawStudentId=String(f.get('studentId')||''),student=students.find(s=>sameId(s.id,rawStudentId)),studentId=student?.id,amount=parseAmount(f.get('amount')),included=Number(f.get('included')),start=String(f.get('start')),end=dueForStudent(student,start,included);if(!studentId||amount<=0||included<=0||!start){alert('Completá los datos del período con valores válidos.');return}setCycles(xs=>[...xs,{id:newId(),studentId,amount,included,start,end,frequency:String(f.get('frequency')),received:parseAmount(f.get('received')),consumed:0,absenceDeducts:false,cancellationDeducts:false,carryOver:false}]);setStudents(xs=>xs.map(s=>sameId(s.id,studentId)?{...s,due:end}:s));setModal(null)}
 const savePayment=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget),rawStudentId=String(f.get('studentId')||''),student=students.find(s=>sameId(s.id,rawStudentId)),rawCycleId=String(f.get('cycleId')||''),cycle=cycles.find(c=>sameId(c.id,rawCycleId)),amount=parseAmount(f.get('amount')),date=String(f.get('date')||today),due=dueForStudent(student,date,cycle?.included);if(!student){alert('Elegí el alumno al que pertenece el pago.');return}if(amount<=0){alert('El importe debe ser mayor a cero.');return}setPayments(xs=>[...xs,{id:newId(),studentId:student.id,amount,date,concept:String(f.get('concept')||'Mensualidad'),cycleId:cycle?.id,method:String(f.get('method')||'Transferencia')}]);setStudents(xs=>xs.map(s=>sameId(s.id,student.id)?{...s,due,paymentDate:date}:s));if(cycle)setCycles(xs=>xs.map(c=>sameId(c.id,cycle.id)?{...c,received:c.received+amount,end:due}:c));setModal(null)}
 const saveStudent=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget),name=`${String(f.get('firstName')||'').trim()} ${String(f.get('lastName')||'').trim()}`.trim(),phone=String(f.get('phone')||'').trim(),amount=parseAmount(f.get('amount')),included=Number(f.get('included')||0),start=String(f.get('start')||today),paymentDate=String(f.get('paymentDate')||start),trainingDays=String(f.get('trainingDays')||''),slots=parseTrainingSchedule(String(f.get('trainingSchedule')||'')),days=slots.length?[...new Set(slots.map(s=>s.day))].sort((a,b)=>a-b):parseTrainingDays(trainingDays),due=calcDue(paymentDate,days,included);if(!String(f.get('firstName')||'').trim()){alert('El nombre es obligatorio.');return}if(amount<0||included<0){alert('Los importes y clases no pueden ser negativos.');return}const duplicate=students.find(s=>s.id!==editingStudent?.id&&s.name.toLowerCase()===name.toLowerCase()&&s.phone.replace(/\D/g,'')===phone.replace(/\D/g,''));if(duplicate&&!window.confirm('Posiblemente este alumno ya está registrado. ¿Deseas crearlo de todos modos?'))return;const student:Student={id:editingStudent?.id||newId(),name,phone,level:String(f.get('level')||'Inicial'),notes:String(f.get('notes')||''),trainingDays:trainingDaysLabel(days),trainingTime:slots[0]?.time||String(f.get('trainingTime')||''),trainingSchedule:formatTrainingSchedule(slots),classesPerWeek:Number(f.get('classesPerWeek')||1),classType:(String(f.get('classType')||'recurrente') as Student['classType']),amount,due,start,paymentDate,included,active:true};const specs:RuleSpec[]=student.classType==='recurrente'?scheduleGroups(slots).map(g=>({days:g.days,time:g.time,duration:60,court:'Cancha 1',start:student.start||today})):[];if(editingStudent){setStudents(xs=>xs.map(s=>s.id===student.id?student:s));setClasses(xs=>xs.map(c=>sameId(c.studentId,student.id)?{...c,student:student.name}:c));const sync=reconcileRules(recurrences,student.id,specs,newId);setRecurrences(xs=>[...xs.filter(r=>!sameId(r.studentId,student.id)),...sync.upserts]);sync.removed.forEach(id=>setClasses(xs=>applyPlan(xs,[],today,id)));setSelectedStudent(student)}else{setStudents(xs=>[...xs,student]);const cycleId=newId();if(amount>0&&included>0)setCycles(xs=>[...xs,{id:cycleId,studentId:student.id,amount,included,start:student.start||today,end:student.due,frequency:`${student.classesPerWeek||1} clase${(student.classesPerWeek||1)>1?'s':''} por semana`,received:0,consumed:0,absenceDeducts:false,cancellationDeducts:false,carryOver:false}]);const sync=reconcileRules([],student.id,specs,newId);if(sync.upserts.length)setRecurrences(xs=>[...xs,...sync.upserts]);setSelectedStudent(student)}setEditingStudent(null);setModal(null)}
 const deleteStudent=(student:Student)=>{if(!window.confirm(`¿Seguro que deseas eliminar a ${student.name}? Se conservará su historial.`))return;setStudents(xs=>xs.filter(s=>s.id!==student.id));setRecurrences(xs=>xs.filter(r=>!sameId(r.studentId,student.id)));setClasses(xs=>xs.filter(c=>c.studentId!==student.id||c.status!=='Programada'));setSelectedStudent(null);setEditingStudent(null);setModal(null)}
const deleteClass=(item:ClassItem)=>{if(item.recurrenceId){setClasses(xs=>xs.map(c=>sameId(c.id,item.id)?{...c,status:'Cancelada' as const,completedAt:today,note:c.note||'Clase quitada del calendario'}:c))}else setClasses(xs=>xs.filter(c=>!sameId(c.id,item.id)));setSelectedClass(null);setModal(null)}
// Materializa las clases de cada alumno como registros reales. Antes se armaban
// en memoria al renderizar, y eso hacia imposible tener historial ni evitar
// duplicados. Ahora cada clase existe como registro y tiene id estable.
const materialize=(list:ClassItem[])=>{let next=list;for(const r of recurrences){if(!r.active)next=applyPlan(next,[],today,r.id)}for(const student of students){const mine=recurrences.filter(r=>r.active&&sameId(r.studentId,student.id));if(!mine.length)continue;const cy=cycles.filter(c=>sameId(c.studentId,student.id));const cycle=cy.find(c=>date(c.start)<=date(today)&&date(c.end)>=date(today))||cy[cy.length-1];const to=cycle?.end&&cycle.end<materializeHorizon?cycle.end:materializeHorizon;const planned=planStudent({rules:mine,studentName:student.name,from:today,to,limit:cycle?.included||0,cycleId:cycle?.id});for(const r of mine){next=applyPlan(next,planned.filter(c=>sameId(c.recurrenceId,r.id)),today,r.id)}}return next}
const weekDays=days.map((_,i)=>iso(addDays(startOfWeek(week),i)),[week])
const studentNameForClass=(item:ClassItem)=>students.find(student=>sameId(student.id,item.studentId))?.name||'Alumno no encontrado'
