 const nav=[['dashboard',LayoutDashboard,'Inicio'],['calendar',CalendarDays,'Calendario'],['students',Users,'Alumnos'],['cash',CircleDollarSign,'Pagos'],['reminders',Bell,'Recordatorios'],['reports',Activity,'Reportes'],['ranking',Users,'Ranking'],['settings',Settings,'Configuración']] as const
 // Mientras se verifica la cuenta no se dibuja ningun dato: si alguien abro la
